/// Knife Trap. Cost 2, Skill, AnyEnemy, Rare. For each *Shiv* in the
/// exhaust pile, **auto-play** that Shiv at the KnifeTrap's target. Bead
/// `sts2-rs-fc00g`: C# `KnifeTrap.cs` `CalculatedShivs` multiplier counts only
/// `Exhaust.Cards.Where(c => c.Tags.Contains(CardTag.Shiv))` — the prior Rust
/// port counted every exhausted card.
///
/// C# `KnifeTrap.OnPlay` (`KnifeTrap.cs:35-49`) does NOT deal raw damage: it
/// iterates the exhaust-pile Shivs and `await CardCmd.AutoPlay(choiceContext,
/// item, cardPlay.Target)` for each, so every Shiv is a REAL card play. The
/// earlier retrofit (`sts2-rs-rez` / `sts2-rs-zol35`) approximated that with a
/// per-Shiv `deal_damage_player_to_enemy`, which skipped the surrounding
/// card-play machinery: no `Before/AfterCardPlayed` hooks fired, so an
/// `AfterimagePower` granted no block (sweep `PLAYER_STATE|KNIFE_TRAP`,
/// block cs=2 rs=1), an on-attack power applied the wrong stack count
/// (`MONSTER_STATE|KNIFE_TRAP`, power amount cs=4 rs=1), and the played Shivs
/// were never re-exhausted in iteration order (the deferred
/// `EXHAUST_FATE|KNIFE_TRAP` exhaust-pile ordering residual). Routing each Shiv
/// through
/// [`sts2_core::combat_loop::auto_play_specific_card_from_exhaust_at_target`]
/// fires the full `OnPlayWrapper` (card-play counters, before/after-play power
/// buses, FanOfKnives AoE redirect, enchantment riders) and re-exhausts the
/// Shiv at the exhaust tail — matching C# exactly. The target is supplied
/// explicitly so no `combat_targets` RNG is consumed (C# `AutoPlay` rolls only
/// for a null target).
///
/// Upgrade rider (C# upgrades each Shiv via `CardCmd.Upgrade(item)` before the
/// auto-play when KnifeTrap is upgraded, `Shiv.OnUpgrade` Damage +2 → 6): flip
/// each Shiv's upgraded flag in the arena before its auto-play so the Shiv's own
/// `OnPlay` reads the upgraded damage. Bead `sts2-rs-zol35`.
/// `CalculatedShivs`: the Shivs sitting in your Exhaust Pile, each of which
/// this card replays. Shared with the card face — see `crate::cards::preview`.
pub(crate) fn preview_knife_trap(
    state: &CombatState,
    _card: &Card,
    _target: Option<CreatureUid>,
) -> i32 {
    i32::try_from(
        state
            .player
            .exhaust
            .iter()
            .filter(|uid| {
                let idx = uid.0.get() as usize - 1;
                state
                    .cards
                    .get(idx)
                    .is_some_and(|c| c.card_id == CardId::Shiv)
            })
            .count(),
    )
    .unwrap_or(i32::MAX)
}

pub(crate) fn play_knife_trap(
    state: &mut CombatState,
    target: Option<CreatureUid>,
) -> EffectResult {
    let t = target.expect("KnifeTrap: Enemy-targeted");
    // C# captures the Shiv list up front (`.ToList()`) BEFORE the auto-play
    // loop, so a Shiv re-exhausted mid-loop is not re-iterated.
    let shiv_uids: Vec<sts2_core::CardUid> = state
        .player
        .exhaust
        .iter()
        .copied()
        .filter(|uid| {
            let idx = uid.0.get() as usize - 1;
            state
                .cards
                .get(idx)
                .is_some_and(|c| c.card_id == CardId::Shiv)
        })
        .collect();
    let upgraded = current_card_upgraded(state);
    for uid in &shiv_uids {
        // C# `CardCmd.AutoPlay` returns immediately when combat is over/ending
        // (`CardCmd.cs:55`); mirror that top guard so a Shiv that ended the
        // fight stops the loop. (Target-death without combat-end keeps going in
        // C#, hitting the corpse as a no-op — matched by not breaking here.)
        if state.is_over {
            break;
        }
        // `CardCmd.Upgrade` is a no-op once `CombatManager.IsEnding`
        // (CardCmd.cs:267-270): a Shiv that downed the last enemy leaves the
        // rest unupgraded (GH #1150).
        if upgraded && !sts2_core::combat_loop::combat_is_ending(state) {
            let idx = uid.0.get() as usize - 1;
            if let Some(card) = state.cards.get_mut(idx) {
                if !card.upgraded {
                    card.upgraded = true;
                    crate::cards::spec_index::apply_spec_upgrade(card);
                }
            }
        }
        let _ = sts2_core::combat_loop::auto_play_specific_card_from_exhaust_at_target(
            state,
            *uid,
            Some(t),
            /*force_exhaust=*/ false,
        );
    }
    EffectResult::Resolved
}

